import type { InterviewSection } from "./types";

export const INTERVIEW_SECTIONS: InterviewSection[] = [

  {
    label: "Beginner",
    color: "#16a34a",
    bg: "#f0fdf4",
    desc: "0-1 year experience. Power, cooling, network, server basics.",
    questions: [
      { n:1, q:"UPS kya hota hai aur DC mein kyun zaroori hai?", answer:"Online Double Conversion UPS: AC→DC→AC. Grid fail pe seamless battery switchover, zero interruption. Battery runtime 10-15 min (DG bridge only). Also conditions power: filters voltage sags, spikes, harmonics. Without UPS — millisecond grid dip = server crash.", why:"Interviewer checking if actual role is understood, not just the name.", expectation:"Must distinguish power conditioning from backup. Must know Online Double Conversion. Must say runtime is DG bridge not long-term backup.", mistake:"'Backup power deta hai' only. Power conditioning equally important.", tip:"First thing on any site: check UPS bypass status. Bypass = load on grid = zero protection. Mention this field habit in interview."},
      { n:2, q:"PUE kya hota hai? Good PUE value kya hoti hai?", answer:"PUE = Total Facility Power ÷ IT Equipment Power. 1.0 theoretical ideal. Real: 1.2-1.4 excellent (hyperscale), 1.5-1.7 good (enterprise), 1.8-2.0 average, >2.0 poor. 1MW IT + 1.6MW total = PUE 1.6 = 600kW overhead.", why:"Primary DC efficiency metric. Context matters — not just formula.", expectation:"Know formula, typical values, and that climate determines what 'good' means. Never say 1.5 is good without qualifying location.", mistake:"Lower PUE always better. Mumbai 1.6 excellent. Iceland 1.6 poor — free cooling should give 1.15.", tip:"Trend matters more than point reading. PUE rising from 1.5 to 1.8 = equipment failure or stranded capacity."},
      { n:3, q:"N+1 aur 2N redundancy mein kya fark hai?", answer:"N = minimum components for load. N+1 = one extra standby. 2N = two complete independent systems each handling 100% load. N+1 example: N=3 CRACs → install 4. 2N example: two full UPS systems — one fails, other takes everything. 2N+1 = most critical environments.", why:"Redundancy is core DC design. Tests if candidate knows practical implications not just definitions.", expectation:"N must be calculated from actual load. 2N requires independence — not just double components on shared infra.", mistake:"N+1 = always 2 units. Wrong — if N=5 then N+1=6.", tip:"N+1 during maintenance = at N — any failure = outage. Know this gap and plan maintenance windows accordingly."},
      { n:4, q:"Hot aisle/cold aisle containment kya hai aur energy mein kaise help karta hai?", answer:"Racks face-to-face = cold aisle (front intake). Back-to-back = hot aisle (exhaust). Containment = physical barriers preventing mixing. Hot exhaust captured → CRAC return → CRAC inlet temperature rises → higher delta-T → same cooling with less airflow → fan energy saved. PUE improvement 0.2-0.3 possible.", why:"Cooling efficiency is major OpEx driver. Interviewer tests thermodynamic understanding, not just label.", expectation:"Must explain WHY containment helps — rising CRAC inlet temperature = higher efficiency. Not just 'prevents mixing'.", mistake:"Containment = blanking panels. Those are rack-level. Aisle containment is completely different scale.", tip:"Thermal camera quarterly — hot spots visible in minutes. I've improved PUE 0.15 with zero hardware spend just by fixing containment gaps."},
      { n:5, q:"VLAN kya hai aur DC mein kyun use karte hain?", answer:"VLAN = IEEE 802.1Q tagging — logical network segmentation on physical switch. DC use: security isolation (iDRAC/production/storage separate), traffic control (iSCSI bandwidth guarantee), compliance (PCI-DSS CDE isolation mandatory), multi-tenant (per-customer isolation). Typical: VLAN 10 Mgmt, 20 Prod, 30 Storage, 40 DMZ.", why:"Networking fundamentals. Daily reality for DC engineer.", expectation:"Know 802.1Q standard. Know trunk vs access port. Know inter-VLAN routing needs L3. Give specific DC use case.", mistake:"VLAN = separate physical network. Wrong — same wire, traffic tagged differently.", tip:"iDRAC VLAN always separate from production. Production compromise = OOB management still secure."},
      { n:6, q:"Tier I se Tier IV classification explain karo.", answer:"Uptime Institute standard. Tier I: single path, no redundancy, 99.671%, 28.8hr downtime/year. Tier II: N+1 components, single path, 99.741%. Tier III: concurrently maintainable, multiple paths (one active), 99.982%, 1.6hr/year. Tier IV: fault tolerant, 2N, dual active paths, 99.995%, 26min/year.", why:"Industry standard — every DC engineer must know cold.", expectation:"Know Tier III allows maintenance without shutdown. Tier IV means ANY fault = zero impact. Must mention cost implication.", mistake:"Tier IV always better. Cost 2x+. Most workloads don't justify Tier IV.", tip:"'Tier certified' vs 'Tier designed' are different things. Uptime Institute certification costs lakhs. Many DCs claim Tier III design without formal cert."},
      { n:7, q:"CRAC aur CRAH mein kya difference hai?", answer:"CRAC: self-contained DX unit, internal compressor + refrigerant, standalone (no chiller plant needed), COP ~2-3. CRAH: uses external chilled water from chiller plant, fan + coil only, no internal refrigerant, COP 4-6. CRAC: smaller DCs, edge, no chiller. CRAH: large DCs >500kW with chiller plant.", why:"Cooling technology selection affects infra requirements fundamentally.", expectation:"Know COP difference. Know CRAH depends on chiller plant (can't work standalone). Know when each is appropriate.", mistake:"CRAH always better. Chiller plant CAPEX, maintenance, and centralized SPOF risk must be factored.", tip:"CRAC filter check monthly. Blocked filter = reduced airflow = hot spots. Thermal imaging finds problems before DCIM alerts do."},
      { n:8, q:"RJ-45 T568B crimping sequence kya hai?", answer:"T568B (commercial standard): Pin 1 White-Orange, 2 Orange, 3 White-Green, 4 Blue, 5 White-Blue, 6 Green, 7 White-Brown, 8 Brown. Straight-through: both ends T568B. Crossover: one T568A one T568B. Modern switches Auto-MDI/MDIX — crossover rarely needed.", why:"Basic structured cabling knowledge for field engineers.", expectation:"Know T568B specifically. Know Auto-MDI/MDIX makes crossover obsolete on modern gear.", mistake:"Still using crossover cables for server-to-switch. Auto-MDI/MDIX handles this automatically on any managed switch.", tip:"Always test with proper cable tester. Visual inspection misses miswired pins that fail at speed."},
      { n:9, q:"IP address aur MAC address mein kya difference hai?", answer:"MAC (L2): 48-bit hardware address, NIC pe burned, local network only, cannot route. IP (L3): 32-bit logical address, software configured, globally routable. ARP bridges them — resolves IP→MAC for local delivery. In DC: VLANs = L2 isolation (MAC), routing between VLANs = L3 (IP).", why:"L2 vs L3 is fundamental troubleshooting knowledge.", expectation:"Know the layers. Know ARP. Connect to DC context — VLAN isolation uses L2.", mistake:"MAC always unique and permanent. MACs can be spoofed. Virtual NICs have virtual/random MACs.", tip:"Troubleshoot with arp -a. Wrong MAC for an IP = conflict. No MAC entry = L2 connectivity broken."},
      { n:10, q:"Single mode aur multimode fiber kya hai?", answer:"SMF (single mode): 9µm core, single light path, 100km+, laser source, yellow jacket. Used inter-DC, long-haul. MMF (multimode): 50µm core, multiple light paths, 300m-2km, LED/VCSEL, aqua/orange jacket. OM3: 10G/300m. OM4: 100G/150m. OM5: 400G WDM. DC: SMF inter-building, OM4 within DC.", why:"Structured cabling fundamentals — wrong fiber type = expensive mistakes.", expectation:"Know core diameter difference. Know OM grades for in-DC use. Know SMF for long-haul.", mistake:"MMF for >300m links — causes signal loss, intermittent errors that are hard to diagnose.", tip:"New DC build: always OM4 minimum. OM5 investment for future 400G without re-cabling."},
      { n:11, q:"DHCP kya hai aur DC mein kab static IP use karte hain?", answer:"DHCP: auto-assigns IP/mask/gateway/DNS via DORA (Discover-Offer-Request-Acknowledge). DC rule: servers, network devices, storage = static (firewall rules and DNS depend on stable IP). Client workstations, laptops, temp devices = DHCP. DHCP reservation (MAC-based) = best of both worlds.", why:"Practical networking — static vs dynamic has real operational consequences.", expectation:"Must know when NOT to use DHCP. Server IP change on DHCP renewal = firewall rules and DNS break.", mistake:"Production servers pe DHCP. IP changes on renewal = application outage.", tip:"DHCP relay/helper-address on L3 switch SVI for cross-VLAN DHCP service."},
      { n:12, q:"Ping ke limitations kya hain DC troubleshooting mein?", answer:"Ping tests: ICMP reachability + RTT latency + packet loss. NOT useful for: application connectivity (ICMP blocked but TCP 443 open = ping works, HTTPS fails), bandwidth, service availability (server pings but app down), port testing. Use telnet/nc/nmap for port tests.", why:"Tool limitations — interviewer checks if candidate goes beyond 'ping works = OK'.", expectation:"Must give ICMP vs TCP example of how ping misleads.", mistake:"Ping success = application working. Most common DC debugging error.", tip:"curl -v https://hostname tests the real application path. Always test actual protocol and port."},
      { n:13, q:"Earthing ka DC mein kya role hai?", answer:"Dual role: 1. Safety — fault current to earth, no voltage buildup on exposed metal, shock protection. 2. Signal quality — reference potential stabilized, ground loops prevented, EMI reduced. Types: Protective Earth (PE) for safety, Functional Earth (FE) for signal. IS:3043: Indian standard, earth resistance <1 ohm for DC.", why:"Safety AND signal integrity both critical in DC.", expectation:"Must mention BOTH roles. Must know IS:3043 standard and measurement requirement.", mistake:"Earthing = just connect a ground rod. Resistance measurement, loop impedance testing, equipotential bonding all needed.", tip:"Annual earth resistance test. Before monsoon is critical — dry season resistance can be higher."},
      { n:14, q:"Server BIOS aur UEFI mein kya difference hai?", answer:"BIOS: 16-bit, MBR, 2.2TB disk limit, slower boot. UEFI: 64-bit, GPT, no size limit, faster boot, Secure Boot, better remote management. DC relevance: configure UEFI via iDRAC/iLO remotely without physical visit. PXE boot, boot order for DR, power management (C-states, ACPI).", why:"Server hardware fundamentals for DC operations.", expectation:"Know UEFI advantages. Mention iDRAC/iLO remote access specifically in DC context.", mistake:"UEFI = just newer BIOS. Secure Boot, GPT, faster boot, remote management are meaningful differences.", tip:"Screenshot existing UEFI config before any changes. Remote UEFI via iDRAC means zero physical visits for config changes."},
      { n:15, q:"RAID levels 0, 1, 5, 6, 10 explain karo.", answer:"RAID 0: stripe only, any disk fail = data loss, speed only. RAID 1: mirror 2 disks, 1 fail tolerated, 50% capacity. RAID 5: stripe+parity, min 3 disks, 1 fail tolerated. RAID 6: double parity, min 4 disks, 2 simultaneous failures tolerated. RAID 10: mirror+stripe, excellent performance+redundancy, 50% capacity. CRITICAL: RAID is NOT backup — ransomware encrypts RAID too.", why:"Storage basics — every DC engineer must know RAID.", expectation:"Know use cases for each. Must proactively say RAID is not a backup substitute.", mistake:"RAID = backup. Ransomware will replicate to all RAID disks. Most dangerous storage misconception.", tip:"Large SSD RAID rebuilds take 24+ hours. During rebuild = one more failure = data loss. Hot spare always present."},
      { n:16, q:"OSI model aur DC troubleshooting mein kaise use karte hain?", answer:"L1 Physical → L2 Data Link (Ethernet/VLAN) → L3 Network (IP/routing) → L4 Transport (TCP/UDP) → L5-6-7 Application. Bottom-up approach: L1: cable seated? link light? L2: VLAN correct? STP blocking? L3: route exists? ARP resolved? L4: port open? TCP handshake? L7: app responding? cert valid?", why:"Systematic troubleshooting — structured approach vs random guessing.", expectation:"Use OSI to explain how to approach a problem. Know which tools map to which layer.", mistake:"Skip L1/L2 immediately. Physical issues waste hours if not checked first.", tip:"'Layer 8' = politics/process. Change ticket approved? SLA impacted? Often delays more than technical issues."},
      { n:17, q:"3-Phase power mein line vs phase voltage kya hai?", answer:"Indian standard: 415V L-L (line-to-line), 240V L-N (line-to-neutral). Line = √3 × Phase = 1.732 × 240 ≈ 415V. Phase voltage (240V): single-phase loads. Line voltage (415V): three-phase loads — UPS, motors, HVAC. DC UPS: input 3-phase 415V, PDU output circuits typically single-phase 240V.", why:"Electrical fundamentals for UPS sizing and PDU selection.", expectation:"Know √3 relationship. Know DC UPS input vs PDU output voltage difference.", mistake:"Confusing single-phase 240V and three-phase 415V in UPS kVA calculations.", tip:"Phase balancing critical in DC. Unbalanced loading causes neutral current, heat, poor UPS efficiency. Monitor per-phase in DCIM."},
      { n:18, q:"/24 subnet kya hai? DC mein common subnets?", answer:"/24 = 255.255.255.0. 24 bits network, 8 bits host. 256 total, 254 usable (.0=network, .255=broadcast reserved). DC subnets: /30=2 hosts (point-to-point), /29=6 hosts (mgmt), /27=30 hosts, /24=254 hosts (typical server VLAN), /22=1022 hosts (large farm).", why:"Subnetting is daily DC network task.", expectation:"Know .0 and .255 reserved. Give DC-specific subnet examples.", mistake:"Using .0 or .255 as host addresses — cannot be assigned.", tip:"Plan with growth in mind: /24 current, /22 allocated for expansion. IP exhaustion post-migration is painful."},
      { n:19, q:"DNS kaise kaam karta hai? DC mein internal DNS kyun important hai?", answer:"Resolution: local cache → /etc/hosts → recursive resolver → root → TLD → authoritative nameserver → IP returned with TTL. DC internal DNS: iDRAC/BMC hostnames, monitoring system hostnames, database CNAME aliases, short TTL for DR failover. Internal DNS failure = DC management disrupted even if internet DNS fine.", why:"DNS is infrastructure not just internet. DC-specific knowledge tested.", expectation:"Know full resolution flow AND DC-specific use cases. Mention TTL and DR.", mistake:"DNS only for internet. Internal DNS failure is more operationally impactful than internet DNS failure.", tip:"dig +trace domain.com shows full resolution path. Test both forward and reverse (PTR) DNS always."},
      { n:20, q:"IPMI/iDRAC/iLO kya hai aur kyun critical hai?", answer:"IPMI: standard for out-of-band server management. Separate BMC chip — works independent of main OS. iDRAC (Dell), iLO (HPE), CIMC (Cisco). Capabilities: remote power control, virtual KVM console, virtual media (ISO mount), hardware health monitoring, BIOS/UEFI access, Serial over LAN. DC reality: physical server room visits = exception not routine.", why:"Primary server management interface. Must know for any DC role.", expectation:"Know it operates independent of OS — even crashed or powered-off server accessible. Know security implications.", mistake:"iDRAC port on production network. Compromise = full server control for attacker.", tip:"Change default credentials on day 1. LDAP integration for iDRAC auth in production."},
    ],
  },

  {
    label: "Intermediate",
    color: "#2563EB",
    bg: "#eff6ff",
    desc: "1-4 years experience. Multi-system integration, protocol depth, operational judgment.",
    questions: [
      { n:21, q:"Generator DC se integrate karne mein kya sequence hoti hai?", answer:"T+0: Grid fails. UPS switches to battery — seamless, zero interruption. T+3-5s: ATS senses loss, sends DG start signal. T+10-30s: DG cranks, reaches 1500 RPM, 50Hz ±2Hz, 415V ±10%. T+30-40s: DG ready, ATS transfers (20-100ms). T+5-10min: DG at full load. Grid returns: ATS transfers back, DG cool-down 5 min unloaded then shutdown.", why:"DG integration sequence — tests field experience vs theory.", expectation:"Must know UPS seamlessly bridges — UPS does NOT fail when grid fails. Must know ATS transfer time vs UPS hold time relationship.", mistake:"UPS fails when grid fails. Wrong — UPS is designed exactly for this scenario.", tip:"Monthly DG test run. Quarterly loaded test — failure modes only surface under real load."},
      { n:22, q:"iSCSI aur Fibre Channel mein fundamental difference kya hai?", answer:"iSCSI: SCSI over TCP/IP on standard Ethernet, dedicated VLAN. Latency milliseconds. Cost: low. FC: purpose-built storage protocol, dedicated FC switches + HBAs. Latency: microseconds. Cost: high. iSCSI: cost-sensitive/smaller DC/no FC expertise. FC: mission-critical databases, banking/healthcare. Modern direction: NVMe-oF displacing both at high-performance tier.", why:"Storage protocol selection — right tool right job.", expectation:"Know when each is appropriate with real examples. Mention NVMe-oF as future direction.", mistake:"FC always better. 25GbE iSCSI with iSER approaches FC performance. Assess workload first.", tip:"iSCSI requires: jumbo frames (MTU 9000), dedicated VLAN, CHAP auth, multipath. All or nothing on performance."},
      { n:23, q:"BGP aur OSPF difference kya hai? DC mein kab kaun?", answer:"OSPF: Link-State, same AS, fast convergence (seconds). Used for internal DC routing. BGP: Path-Vector, between ASes, deliberately slow (stability), policy-based. DC use: OSPF internal fabric, BGP for ISP uplinks and cloud connectivity (Direct Connect/ExpressRoute = BGP). Hyperscale: BGP Unnumbered everywhere even internal Spine-Leaf.", why:"Routing protocol knowledge fundamental for DC network engineers.", expectation:"Clearly differentiate internal vs external use. Must know cloud connectivity uses BGP.", mistake:"OSPF faster always. BGP deliberately slow for stability. BGP dampening prevents route oscillation.", tip:"Spine-Leaf + BGP ECMP: multiple spines = equal-cost paths = automatic load balancing. More scalable than OSPF at large scale."},
      { n:24, q:"VM aur Container mein fundamental difference kya hai?", answer:"VM: hypervisor, complete Guest OS, strong isolation, boot 30-90s, GBs size. Container: shares host OS kernel, app+dependencies only, boot milliseconds, MBs size. Density: 50-100 VMs vs 1000+ containers per server. Security: container isolation weaker — container escape vulnerabilities exist. Production reality: VMware cluster running K8s worker nodes (VMs + containers both).", why:"Virtualization evolution — modern DC uses both.", expectation:"Know isolation difference. Know they coexist in production. Know when VMs still preferred.", mistake:"Containers always better. Stateful databases, regulated workloads still better on VMs.", tip:"vMotion: live VM migration without downtime. Enables hardware maintenance without server downtime — core DC capability."},
      { n:25, q:"Stranded capacity kya hai aur DC mein kaise hoti hai?", answer:"Stranded capacity = provisioned power/cooling allocated but unused — yet unavailable for others. Causes: teams request 20kW use 8kW, legacy servers not decommissioned, nameplate vs actual (server rated 500W draws 200W), worst-case planning. Problem cascades: rack→PDU→UPS capacity all consumed on paper. Fix: smart PDUs, DCIM, regular audits, decommission process.", why:"Capacity planning core DC operations function.", expectation:"Know cascading effect through power chain. Know smart PDUs as measurement solution.", mistake:"Allocated = used. Average server utilization 15-25% in typical enterprise DC.", tip:"Track three numbers: nameplate installed vs allocated vs measured draw. Gap = stranded capacity. Report weekly to capacity team."},
      { n:26, q:"Power factor kya hai aur DC mein kyun matters?", answer:"PF = Real Power (kW) / Apparent Power (kVA). PF 1.0 = all apparent is real. PF 0.8 = 20% reactive/wasted. Old UPS output PF 0.8: 100kVA = 80kW useful. Modern UPS output PF 1.0 = 100kVA = 100kW useful. Utility billing: some Indian utilities charge on kVA — low PF = higher bill. Cable sizing: low PF = higher current for same real power.", why:"Electrical engineering fundamental affecting UPS sizing and utility costs.", expectation:"Know kW vs kVA. Know modern UPS output PF is 1.0 vs old 0.8. Know utility billing implication.", mistake:"100kVA UPS = 100kW capacity always. Only true with PF 1.0 output.", tip:"Old UPS (PF 0.8): if IT load is 90kW at PF 0.9 = 100kVA apparent → overloads old 100kVA UPS despite seemingly fitting."},
      { n:27, q:"Chiller plant mein free cooling kaise integrate karte hain?", answer:"Free cooling (economizer): outdoor ambient low → bypass compressor, use cooling tower water directly. Waterside: cooling tower water → plate heat exchanger → CRAH (no chiller). Trigger: outdoor wet-bulb < CHW supply temp - 5-8°C approach temperature. PUE impact: Delhi 1000-1500 free cooling hours/year → PUE 1.55→1.18 in winter. Mumbai <100 hours. Nordic 4000+ hours.", why:"Biggest single PUE improvement lever. Tests cooling system depth.", expectation:"Know waterside economizer specifically. Know climate determines feasibility.", mistake:"Free cooling = zero cost. Cooling tower fans/pumps still run. 'Free' means no compressor operation.", tip:"NPV calculation before investment. Delhi DC case: free cooling CAPEX recovered in 2.5 years from energy savings."},
      { n:28, q:"STP kya hai aur modern DC mein kyun problematic hai?", answer:"STP (802.1D): L2 loop prevention via port blocking. Classic STP convergence 30-50 seconds — unacceptable in DC. RSTP 1-2 seconds — better but still slow. Modern DC solution: Spine-Leaf pure L3 fabric. No L2 loops by design. No STP needed. ECMP instead of STP blocked ports.", why:"STP is root cause of many DC network incidents. Professional should understand modern alternative.", expectation:"Know specific convergence times and why unacceptable. Know Spine-Leaf as modern solution.", mistake:"STP everywhere is safe. BPDU Guard misconfiguration + STP = broadcast storm risk.", tip:"BPDU Guard on all access ports. PortFast on server ports. Root Guard on designated ports. Prevents miscabling-induced storms."},
      { n:29, q:"Hyperconverged Infrastructure (HCI) kya hai?", answer:"HCI: compute + storage + networking integrated. Software-defined storage across nodes. Products: VMware vSAN, Nutanix AOS, Dell VxRail, Azure Stack HCI. Benefits: simpler (fewer systems), linear scale-out (add node = add compute+storage), single management. Tradeoffs: shared failure domains, less granular scaling, proprietary licensing expensive.", why:"HCI common in enterprise DC for edge and VDI.", expectation:"Know what HCI replaces (separate SAN + compute). Know TCO analysis needed.", mistake:"HCI always cheaper. Per-VM cost analysis needed. Large-scale SAN often cheaper per GB.", tip:"HCI sizing: calculate compute and storage needs independently, then find node satisfying both. Mismatch = stranded capacity."},
      { n:30, q:"Spine-Leaf architecture kya hai aur 3-tier se better kyun hai?", answer:"Spine-Leaf: every Leaf connects to every Spine. Any server-to-server = always 2 hops. No STP (pure L3), ECMP active-active on all uplinks. Linear scale: add Leaf = new rack, add Spine = more bandwidth. 3-tier (old Core-Aggregation-Access): variable hop count, STP blocking, poor east-west traffic, hard to scale.", why:"Modern DC architecture standard. Evolution must be understood.", expectation:"Know 2-hop guarantee and ECMP. Know east-west traffic as the driver for change.", mistake:"Spine-Leaf = always 2 physical switches. Wrong — number of each scales independently.", tip:"East-west traffic >> north-south in modern microservices DC. 3-tier built for client-server north-south traffic — doesn't scale."},
      { n:31, q:"UPS bypass kya hai aur kab occur hota hai?", answer:"Bypass: direct grid→load, bypassing rectifier+battery+inverter. Load unprotected — no battery, no conditioning. Automatic (static bypass): thyristor-based, triggered by UPS fault (overload, inverter failure). Manual (maintenance bypass): physical switch, for major UPS maintenance. Risk: grid fault during bypass = immediate server outage.", why:"UPS bypass is critical operational event. Tests response protocol knowledge.", expectation:"Know bypass = unprotected state. Know automatic vs manual distinction. Know immediate risk.", mistake:"Bypass is just a 'mode' — it's safe. Bypass is high-risk: grid quality directly affects servers.", tip:"2 AM bypass alarm = senior engineer call immediately. Document root cause before returning to inverter."},
      { n:32, q:"SNMP kya hai aur DC monitoring mein kaise use hota hai?", answer:"SNMP: network device management protocol. Manager GETs data from devices, devices send TRAPs on events. v1/v2c: community string (plaintext = insecure). v3: authentication + encryption (use in production). MIB = database of OIDs (what can be monitored). DC use: UPS, CRAC, switches, servers → central NMS (Nagios, Zabbix, Prometheus).", why:"Monitoring backbone for DC infrastructure.", expectation:"Know v3 vs v2c security difference. Know MIB/OID concept. Give specific DC device examples.", mistake:"Default community string 'public'. Anyone on network can read all device data.", tip:"Request MIB files from OEM at commissioning. Getting them post-deployment takes weeks of vendor support."},
      { n:33, q:"Load balancer kya karta hai? L4 vs L7 kya hai?", answer:"Load Balancer: distributes incoming traffic across multiple servers. Prevents overload, provides HA. L4: TCP/UDP level, fast, no session awareness — by IP:port only. L7: HTTP/HTTPS level, URL routing, SSL termination, cookie persistence, content switching. Hardware: F5 BIG-IP, Citrix ADC. Software: HAProxy, Nginx. Cloud: AWS ALB/NLB, Azure LB. Health checks remove unhealthy servers automatically.", why:"LB critical for production DC HA and scaling.", expectation:"Know L4 vs L7 difference and when each is appropriate. Mention SSL termination at L7.", mistake:"DNS Round Robin = load balancer. No health checking, no session persistence, slow failover (TTL-based).", tip:"SSL termination at LB: servers see plain HTTP → simpler app, better performance. Certs managed on LB only."},
      { n:34, q:"Backup aur replication mein difference kya hai?", answer:"Backup: point-in-time copy, scheduled, requires restore time (RPO = backup interval). Replication: continuous data copy, near-real-time, always running. Why both: backup protects against accidental deletion and ransomware (pre-infection point-in-time). Replication protects against DR scenarios. Critical: ransomware encrypts primary → replication copies encrypted data immediately. Only backup (pre-infection) can restore.", why:"Data protection architecture — dangerous confusion here.", expectation:"Must explain ransomware protection immediately as why replication doesn't replace backup.", mistake:"Replication = backup. Ransomware will replicate to all destinations. Most dangerous storage misconception.", tip:"3-2-1-1 rule: 3 copies, 2 media, 1 offsite, 1 air-gapped/immutable. The last '1' is ransomware protection."},
      { n:35, q:"Cisco switch pe VLAN configuration kaise karoge?", answer:"vlan 20 → name PRODUCTION. int gi0/1: switchport mode access, switchport access vlan 20, spanning-tree portfast. int gi0/24 (uplink): switchport mode trunk, switchport trunk allowed vlan 10,20,30. Verify: show vlan brief, show interfaces trunk, show interfaces gi0/1 switchport.", why:"Practical configuration knowledge — conceptual without CLI skills = incomplete.", expectation:"Know exact commands. Mention PortFast on access ports. Explicitly list allowed VLANs on trunk.", mistake:"'Allow all VLANs' on trunk — security risk. Unknown VLANs traverse trunks unnecessarily.", tip:"Post-config: always verify with show commands before closing change ticket. Never assume config took effect."},
      { n:36, q:"IP conflict kya hota hai aur kaise resolve karte hain?", answer:"Two devices same IP = ARP table flapping. Both intermittently lose connectivity. Symptoms: Windows Event Log IP conflict warning, DHCP logs 'address in use', ARP table same IP different MAC alternating. Resolution: arp -a from known-good host → note competing MACs → identify devices by MAC → change one device IP → update DNS + firewall rules → IPAM update.", why:"Common DC troubleshooting — quick resolution expected.", expectation:"Know arp -a command specifically. Know IPAM as prevention tool.", mistake:"Switch reboot to fix conflict. ARP table clears temporarily but conflict immediately returns.", tip:"Prevention: IPAM tool mandatory. Every static IP assignment tracked. DHCP leases logged and audited."},
      { n:37, q:"TCP aur UDP fundamental difference kya hai?", answer:"TCP: connection-oriented (3-way handshake), reliable (ACK+retransmit), ordered, flow control, higher overhead. UDP: connectionless, no ACK, unordered, low overhead, low latency. DC: TCP = HTTP/S, database connections, iSCSI, file transfer. UDP = DNS queries, DHCP, SNMP traps, VoIP, video. Firewall rules: always specify TCP vs UDP explicitly.", why:"Protocol fundamentals for firewall rules and troubleshooting.", expectation:"Know which DC services use which protocol. Know firewall rule implication.", mistake:"UDP = unreliable = bad. Applications choose UDP deliberately when latency > reliability.", tip:"DNS = UDP 53 (queries) + TCP 53 (zone transfers). Both must be in firewall rules for DNS servers."},
      { n:38, q:"PAT kya hai aur DC mein kahan use hota hai?", answer:"PAT/NAT Overload: multiple private IPs → single public IP, differentiated by source port numbers. 192.168.1.10:1234 → 203.0.113.1:10234. DC use: servers with private IPs accessing internet, management network egress. NOT for inbound DC traffic (use 1:1 static NAT or public IPs). NAT table can exhaust 64K ports per public IP at high connection volume.", why:"NAT fundamentals in DC networking.", expectation:"Know 64K port exhaustion risk. Know inbound vs outbound NAT difference.", mistake:"PAT = slow. Modern hardware NAT at line rate — millions of translations per second.", tip:"Monitor NAT table utilization on firewalls. High-connection-rate servers can exhaust PAT pool — add more public IPs."},
      { n:39, q:"Server decommissioning process kya hona chahiye?", answer:"1. Business approval + owner sign-off. 2. App team sign-off + dependency check. 3. Final data backup + migration. 4. DNS records removed, IP released to IPAM. 5. Remove from monitoring. 6. Access revoked (AD, SSH keys, firewall rules). 7. Physical disconnect (labeled cables). 8. Data destruction (DoD 7-pass or crypto-erase SSD) + certificate. 9. CMDB update + asset scan-out. 10. Hardware disposition per e-waste policy.", why:"Decommissioning affects security, compliance, and capacity planning.", expectation:"Mention data destruction certificate specifically. Know powered-off ≠ decommissioned.", mistake:"Power off and forget. Abandoned servers: IP allocated, DNS active, data not wiped, stranded rack capacity.", tip:"Quarterly zombie server audit: zero network traffic 60+ days → initiate decommission. Compliance and security liability."},
      { n:40, q:"HT/LT panel aur transformer — DC power flow explain karo.", answer:"Utility HT supply (11kV/33kV) → HT Panel (HT breakers, protection relays OC/EF, metering) → Step-down Transformer (11kV→415V, oil-cooled ONAN/ONAF or dry-type) → LT Panel/MLDB (ACBs/MCCBs, 415V) → UPS → PDU → Rack PDU → Servers. Tier III/IV: dual HT feeders from different substations.", why:"Full power chain understanding for senior DC engineers.", expectation:"Trace complete path from utility to server. Know dual utility supply requirement for Tier III.", mistake:"Ignoring HT yard. Utility supply reliability affects DC availability as much as UPS design.", tip:"Dual utility from same substation = not true diversity. Different substations required for genuine redundancy."},
      { n:41, q:"VPN kya hai? Site-to-Site vs Remote Access difference?", answer:"VPN: encrypted tunnel over internet for private connectivity. Site-to-Site: fixed locations (DC-to-DC, DC-to-cloud), always-on, IKEv2/IPsec. AWS Site-to-Site VPN, Azure VPN Gateway. Remote Access: individual users to DC, user-initiated, SSL VPN or IKEv2. AnyConnect, OpenVPN, GlobalProtect. DC context: Site-to-Site for cloud hybrid, Remote Access for engineers.", why:"VPN fundamental for hybrid DC connectivity.", expectation:"Clearly differentiate two types with DC examples.", mistake:"VPN = only for remote employees. Site-to-site for DC-to-cloud is equally critical.", tip:"IKE rekeying failure = VPN drops every 24 hours if not configured correctly. Monitor VPN tunnel uptime."},
      { n:42, q:"Firewall types — stateful vs stateless difference kya hai?", answer:"Stateless: packet-by-packet, checks IP/port/protocol independently. Fast but limited. Stateful: tracks connection state table — 'is this packet part of established connection?' More secure. NGFW (L7): application awareness, DPI, IPS/IDS. DC: NGFW at perimeter (Palo Alto, Fortinet, Check Point). Internal microsegmentation for east-west.", why:"Firewall is critical DC security component.", expectation:"Clearly explain connection state tracking. Know NGFW vs basic firewall difference.", mistake:"Stateful = slow. Modern stateful firewalls line-rate — negligible performance difference.", tip:"Rule base review quarterly: any any-any rules? Rules for decommissioned services? Bloat creates management and audit issues."},
      { n:43, q:"Cable management DC mein kyun important hai?", answer:"Cable management affects: 1. Airflow — front-blocking cables = hot spots. 2. Safety — floor cables = trip hazard, evacuation risk. 3. Maintenance — poor management = wrong cable pulled = outage. 4. Future changes — clean cables = faster safer changes. 5. Documentation — labeled cables = faster troubleshooting. Best practice: structured managers (horizontal+vertical), color coding, labels both ends, zero cables on raised floor.", why:"Operational excellence — cable management is daily DC ops reality.", expectation:"Connect cable management to airflow impact specifically. Mention safety implications.", mistake:"Cable management = cosmetic. Poor cable management caused 35°C hot spots I've personally resolved.", tip:"Before any maintenance: photograph cable layout. After: verify unchanged. Document before touching."},
      { n:44, q:"DMZ kya hai aur DC mein kyun zaroori hai?", answer:"DMZ (Demilitarized Zone): network segment between internet and internal network. Hosts internet-facing services (web servers, email gateways, DNS, public APIs, load balancers). Traffic: Internet→DMZ limited to published ports only. DMZ→Internal: restricted to specific DB ports, specific IPs only. Internal→DMZ: management traffic. Breach containment: attacker in DMZ ≠ access to internal.", why:"DMZ is fundamental DC layered security architecture.", expectation:"Explain traffic flow between all three zones. Know specific services in DMZ.", mistake:"No DMZ — all servers on internal network. Single perimeter breach = full access to all systems.", tip:"Modern trend: zero trust replacing DMZ concept. But DMZ still relevant for perimeter and legacy workloads."},
      { n:45, q:"NTP kya hai aur DC mein kyun critical hai?", answer:"NTP: clock synchronization across network devices. DC critical because: log correlation (timestamps must match for incident investigation), TLS certificates (clock drift = cert validation failure), Kerberos auth (requires clocks within 5 minutes), SNMP trap timestamps, database replication (transaction ordering). Hierarchy: Stratum 0 (atomic) → Stratum 1 (NTP server) → Stratum 2 (DC devices).", why:"Time synchronization is invisible infrastructure — only noticed when broken.", expectation:"Give specific examples of what breaks with time drift. Kerberos and log correlation are key.", mistake:"NTP is optional nice-to-have. Kerberos breaks at >5 min drift. Security logs become useless.", tip:"Monitor NTP stratum and drift on all devices. Alert if stratum changes — upstream NTP connection lost."},
      { n:46, q:"DCIM vs BMS — kya difference hai?", answer:"BMS: building infrastructure management — HVAC control, electrical monitoring, fire alarm interfaces, access control. Protocols: BACnet, Modbus. DCIM: IT + infrastructure integrated — per-rack power monitoring, thermal maps, capacity planning, asset management, change management. DCIM consumes BMS data. BMS doesn't understand rack density or server load. DCIM does.", why:"DCIM and BMS are core DC management tools. Role clarity tested.", expectation:"Clearly differentiate scope. Mention BACnet/Modbus integration between them.", mistake:"DCIM = BMS. Different scopes, different systems, must be integrated.", tip:"Start DCIM with power monitoring only — quickest ROI. Prove value then expand scope."},
      { n:47, q:"MTU aur jumbo frames DC networking mein kyun matter karte hain?", answer:"MTU: max packet size without fragmentation. Default Ethernet: 1500 bytes. Jumbo frames: 9000 bytes (MTU 9000). DC use: iSCSI storage (MTU 9000 mandatory for performance), NFS, VMware vMotion. Requirement: ALL devices in path must support MTU 9000 — server NIC, switch ports, storage ports. One mismatch = fragmentation or drop. Test: ping -M do -s 8972 target.", why:"MTU mismatch is common subtle DC performance issue.", expectation:"Know which DC protocols need jumbo frames. Know all devices in path must match.", mistake:"Enable MTU 9000 on servers but not switches — packets fragmented or silently dropped. Intermittent storage errors.", tip:"Test MTU during initial setup. Binary search with ping -s to find exact MTU limit in path."},
      { n:48, q:"vMotion kya karta hai aur DC mein kyun valuable hai?", answer:"vMotion: live VM migration between ESXi hosts with zero downtime. Process: iterative memory copy to destination → brief pause (milliseconds) → final sync → VM resumes on destination. Requires: shared storage (both hosts access same LUN), compatible CPU families, same VLAN accessible on both hosts. DC use: ESXi host hardware maintenance without VM downtime.", why:"vMotion is one of most powerful DC operations capabilities.", expectation:"Know shared storage requirement. Explain memory copy process. Give maintenance use case.", mistake:"vMotion works between any ESXi hosts. CPU compatibility, shared storage, and network consistency are all prerequisites.", tip:"Storage vMotion = move VM disk while running. Different from vMotion (compute migration). Can change datastore online."},
      { n:49, q:"Server common failure modes kya hain?", answer:"PSU failure: dual PSU servers protected — one fails, other carries. Check PSU LEDs weekly. CPU/DIMM: POST errors, BSOD, escalating ECC errors. Fan failure: temperature rise, throttling, shutdown. HDD/SSD: SMART errors, RAID degraded, latency spike. NIC: link flapping, CRC errors increasing. PDU circuit trip: all servers on circuit down simultaneously.", why:"Failure mode knowledge = proactive maintenance and fast incident response.", expectation:"Know dual PSU protection depends on separate power paths. Know ECC correctable errors as leading indicator.", mistake:"Dual PSU = no power risk. Dual PSU from same PDU = single PDU failure takes both PSUs simultaneously.", tip:"iDRAC/iLO hardware event log monthly review. Increasing correctable ECC = replace DIMM proactively before uncorrectable."},
      { n:50, q:"PXE boot kya hai aur DC mein kaise use hota hai?", answer:"PXE: boot from network without local OS. NIC sends DHCP broadcast → gets IP + TFTP boot server → downloads boot image. DC use: automated OS deployment (new server boots → receives OS installer), diskless VMs, rescue boot (corrupt OS → remote recovery), automated provisioning (Chef/Puppet triggered post-OS install). Requires: DHCP with PXE options 60/66/67, TFTP server, boot image.", why:"Automated server provisioning — DC at scale requires this.", expectation:"Know DHCP role in PXE. Explain how it enables automated provisioning.", mistake:"PXE only for initial OS install. Rescue/recovery booting equally valuable operationally.", tip:"DHCP helper-address must forward PXE options across VLANs. Missing this = PXE works in one VLAN only."},
    ],
  },

  {
    label: "Senior Engineer",
    color: "#7c3aed",
    bg: "#faf5ff",
    desc: "5+ years. Architecture, capacity, advanced operations, systemic thinking.",
    questions: [
      { n:51, q:"Tier III aur Tier IV operational difference kya hai?", answer:"Tier III: N+1, concurrently maintainable (any component maintained without IT load shutdown), dual paths one active, 99.982%, 1.6hr downtime/year. Tier IV: 2N, fault tolerant (any fault = zero impact), dual active paths, 99.995%, 26 min/year. Design changes T3→T4: UPS N+1→2N independent, dual PDU per rack (from separate UPS), cooling 2N separate loops, generators 2N dual ATS.", why:"Tier classification drives design cost operations — must know cold.", expectation:"Know maintenance implications differ. T3 needs maintenance windows. T4 does not. Know actual downtime figures.", mistake:"Tier IV always better. Cost 2x+. Most enterprise workloads don't need Tier IV.", tip:"Find actual SPOFs in documentation — don't trust marketing tier claims. Walk the floor and verify."},
      { n:52, q:"DC capacity planning methodology kya hai?", answer:"Four dimensions: Power (measured IT load not nameplate, 3-5yr growth forecast, PUE target, 20-30% headroom), Cooling (IT kW, zone density, free cooling opportunities), Space (rack count, floor loading 600-1200 kg/m²), Network (BW, east-west ratio, spine saturation). Method: measure actual draw (smart PDUs) → growth model → constraint analysis (what runs out first?) → scenario planning → refresh cycle planning (hardware refresh 3-5yr = density increase).", why:"Capacity planning is senior DC role.", expectation:"Know measured draw vs nameplate. Identify which resource is the binding constraint first.", mistake:"Planning for 100% utilization. Always 20-25% headroom minimum.", tip:"500-server DC: nameplate 500kW allocated, measured 280kW — 220kW stranded. Smart PDUs reveal this immediately."},
      { n:53, q:"DCIM implementation mein kya real challenges hain?", answer:"1. Data quality: existing data inaccurate (wrong rack positions, wrong allocations). Garbage in = garbage out. 2. Integration complexity: BMS BACnet/Modbus, UPS SNMP, switches REST — each OEM needs separate integration work. 3. Org change: operations team resistance, workflow changes. 4. Accuracy vs completeness: months before useful — prioritize power first. 5. Ongoing maintenance: DCIM only useful if kept current after every asset move.", why:"Real implementation challenges — not marketing pitch.", expectation:"Give specific technical challenges (protocol diversity) AND organizational (change management).", mistake:"DCIM as panacea. Many expensive deployments become shelfware.", tip:"Start power monitoring only. Prove ROI. Then expand to thermal, capacity, change management in that order."},
      { n:54, q:"DR site pe active-active vs active-passive kaise decide karte hain?", answer:"Active-Active: both sites serving traffic, near-zero RTO/RPO, expensive. Requires stateless apps or globally distributed DB, real-time replication, <20ms inter-site latency, DNS load balancing. Active-Passive: Cold (restore from backup, RTO hours), Pilot Light (DB replica only running, RTO 30-60 min), Warm Standby (scaled-down running, RTO minutes). Decision: RPO/RTO business requirement, app architecture (stateful?), inter-site distance, budget.", why:"DR architecture is senior design decision with major cost implications.", expectation:"Know stateful applications complicate active-active. Know synchronous replication distance limits (~80km for zero data loss).", mistake:"Active-active always better. Significantly more expensive. Most apps not designed for it.", tip:"Database is DR's hardest problem. Sync replication = zero loss but latency overhead. Distance limit for sync: ~80km round-trip budget."},
      { n:55, q:"Fire suppression system design kaise karte hain DC mein?", answer:"Layered approach. Detection: VESDA (incipient stage, 1-2hr before visible smoke), conventional smoke detectors (confirmation), heat detectors (backup). Suppression: clean agent FM200/Novec for server rooms (no residue, electronics safe, complete flooding in 10s), pre-action sprinkler for large mechanical areas (2-event required). Zoning: server hall, UPS room, battery room separate. Regulatory: NBC, IS:15908, FM Global.", why:"Fire suppression is life safety. Senior engineer must understand complete strategy.", expectation:"Know VESDA vs conventional detection difference. Know zone separation rationale. Know FM200 vs Novec.", mistake:"Single zone suppression for entire DC. False discharge in one zone shouldn't discharge whole DC.", tip:"Suppression inhibit during maintenance — VESDA isolated temporarily. Re-enable immediately after work. Document every inhibit."},
      { n:56, q:"Multi-cloud vs hybrid cloud kab choose karte hain?", answer:"Hybrid: on-prem + public cloud tightly integrated. Best for: legacy apps on-prem, RBI compliance (India data residency), investment protection, gradual migration. Multi-cloud: multiple public providers. Best for: vendor lock-in avoidance, best-of-breed (BigQuery GCP, Azure identity, AWS mature DBs), geographic coverage, regulatory requiring specific provider per jurisdiction. Decision: data gravity → regulatory → latency → cost → team skills.", why:"Cloud strategy is now core DC engineering decision.", expectation:"Clearly differentiate architectures. Know business drivers for each.", mistake:"Cloud mein sab migrate karo. Latency-sensitive, data-heavy, RBI-regulated workloads may not suit cloud.", tip:"Decision order: Regulatory constraint first (non-negotiable) → data gravity → latency → cost → optimization."},
      { n:57, q:"Physical security layers kya hone chahiye DC mein?", answer:"Perimeter: compound wall, CCTV, vehicle barriers (bollards), guard post. Building: card+PIN or biometric access, man-trap (anti-tailgating), visitor management system. Data hall: separate access per hall/cage, biometric preferred, CCTV inside server room. Rack level: locking cabinets (colo). Logging: all access events timestamped, CCTV correlation, 90 days minimum retention (1 year PCI-DSS).", why:"Physical security as important as cyber security in DC.", expectation:"Mention man-trap as technical tailgating prevention. Know retention requirements.", mistake:"'I know that person' = hold the door. If not badged in = not authorized. Culture must match physical controls.", tip:"Annual physical penetration test — hire red team. You will always find gaps."},
      { n:58, q:"DC audit karte waqt kya kya check karte hain?", answer:"Physical: SPOF mapping vs design docs, redundancy verification (actual vs documented), maintenance records compliance, deferred maintenance register. Operational: change management compliance, incident drill records, emergency procedure docs, training records. Compliance: access log audit, environmental data (within spec consistently?), PCI-DSS/ISO 27001 if applicable. Documentation: as-built vs actual installation (spot-check), CMDB accuracy (verify 10 random assets physically).", why:"Audit skills valuable for senior engineers assessing vendor or internal DCs.", expectation:"Go beyond documentation to physical verification. Drawings often don't match reality.", mistake:"Documentation audit only. As-built drawings frequently don't match actual installation.", tip:"Biggest audit finding: deferred maintenance. 'We were going to do it next quarter' — quantify deferred items as risk."},
      { n:59, q:"RCA kaise karte hain DC incident ke baad?", answer:"Within 48-72 hours. 1. Timeline construction: exact timestamps from ALL systems — no approximations. 2. 5 Whys: Why servers down? → UPS tripped. Why? → Overload. Why overload? → Servers added = 95% load. Why at 95%? → No capacity check. Why no check? → No approval process. Root cause = missing capacity process. 3. Contributing vs direct vs systemic causes. 4. Action items: preventive + corrective + detective, each with owner and deadline.", why:"RCA culture separates mature operations from reactive firefighting.", expectation:"Know 5 Whys technique. Distinguish direct vs systemic causes.", mistake:"Blame individual. Good RCA: root cause is always a process or system failure.", tip:"Fishbone (Ishikawa) diagram for complex incidents: Machine, Method, Material, Man, Environment, Measurement categories."},
      { n:60, q:"BMS aur DCIM integration mein kya challenges hain?", answer:"1. Protocol mismatch: BMS uses BACnet/Modbus, DCIM uses SNMP/REST. Translation layer needed per OEM. 2. Data granularity: BMS collects building level (total CRAC flow), DCIM needs rack level. Gap cannot be filled from BMS alone. 3. Off-list integrations: expensive custom work. 4. Poll latency: BMS 30-60s acceptable for building control, DCIM needs <10s for accurate thermal maps. 5. Dual alarm systems: gaps and duplications both possible.", why:"Real integration complexity — marketing demos make this look easy.", expectation:"Name protocols (BACnet, Modbus) specifically. Explain granularity problem.", mistake:"Vendor integration works out-of-box. Always test in non-prod first after every version upgrade.", tip:"Document BMS point list → DCIM variable mapping. Invaluable during system replacement or version upgrades."},
      { n:61, q:"Chiller plant mein condenser water treatment kyun critical hai?", answer:"Cooling tower + chiller water circulates continuously. Without treatment: 1. Scaling: calcium/magnesium deposits on heat exchanger → reduced heat transfer → chiller works harder → PUE degrades. 2. Biological: Legionella pneumophila in warm water → health risk + legal liability. 3. Corrosion: pipe leaks → system failure. Treatment: biocide (Legionella prevention), scale inhibitor, corrosion inhibitor, blowdown. Monthly monitoring: pH, conductivity, inhibitor levels.", why:"Water treatment failure is silent PUE degrader and health risk.", expectation:"Know Legionella risk specifically. Know PUE impact of scaling.", mistake:"Water treatment optional. Legionella outbreak = facility shutdown + legal action.", tip:"Water treatment specialist contract mandatory. In-house monthly monitoring. Third-party audit quarterly."},
      { n:62, q:"SAN fabric mein zoning aur LUN masking kya hai?", answer:"Zoning: FC switch level. Defines which HBAs can communicate with which storage ports. Hard zoning (by port) = preferred — WWPN not spoofable. Soft zoning (by WWN) = less secure. LUN masking: storage array level. Defines which hosts can access which LUNs. Both needed: zoning = fabric isolation, LUN masking = storage access control. Defense in depth. Single-initiator zones: one HBA per zone with storage ports.", why:"SAN security and management for storage-heavy DC engineers.", expectation:"Know zoning vs LUN masking operate at different layers. Know hard vs soft zoning security difference.", mistake:"Only zoning OR only LUN masking. Both needed for complete isolation.", tip:"Stale zones after server decommission = security risk + management complexity. Zone cleanup as part of decommission checklist."},
      { n:63, q:"SPAN aur RSPAN kya hai? DC mein kab use karte hain?", answer:"SPAN: copy traffic from source port/VLAN to destination port on same switch. RSPAN: remote SPAN — extends across switches via trunk. ERSPAN: encapsulated via GRE tunnel to any IP destination. DC use: network troubleshooting (Wireshark capture), IDS/IPS feed, security forensics, performance analysis. Limitation: CPU-intensive at high traffic — impacts switch performance.", why:"Network monitoring tools — senior engineers use SPAN for deep troubleshooting.", expectation:"Know performance impact. Know when RSPAN vs SPAN needed (different switches).", mistake:"SPAN always safe. High-traffic SPAN sessions impact switch CPU significantly in production.", tip:"Temporary SPAN sessions only. Never leave permanent SPAN without documented purpose and duration."},
      { n:64, q:"DC mein power quality issues kya hote hain aur kaise detect karte hain?", answer:"Issues: 1. Voltage sags (80-90% nominal) — server restarts. 2. Voltage swells (overvoltage) — equipment damage. 3. Harmonics (THD from UPS, VFDs) — distorted sine wave, heat in cables. 4. Transients/spikes — equipment damage. 5. Power factor (reactive power waste). Detection: power quality analyzer (Fluke 1760), UPS SNMP input voltage/frequency history, BMS power monitoring, DCIM metrics.", why:"Power quality affects equipment reliability and UPS efficiency.", expectation:"Know THD as specific metric. Know what causes each issue.", mistake:"Grid supply always clean. Grid has many quality issues — that's exactly why UPS exists.", tip:"Mine UPS SNMP historical data for voltage/frequency trends. Degrading grid quality visible before it causes outages."},
      { n:65, q:"Cooling capacity shortage ka emergency plan kya hona chahiye?", answer:"Thresholds: 28°C inlet = alert. 30°C = begin controlled load shedding. 35°C = emergency shutdown non-critical systems. Immediate: identify zone, check remaining CRAC/CRAH capacity, maximize cooling output. Short-term: portable precision cooling units (keep 2 on-site always), temporary containment reinforcement, non-essential workload power-off. Application team notification mandatory from 28°C.", why:"Emergency planning is senior engineer responsibility.", expectation:"Give specific temperature thresholds. Know portable cooling units as emergency resource.", mistake:"Increase CRAC setpoints first. Find root cause first, then adjust.", tip:"Portable precision cooling units: rental lead time is days. Keep 2 on-site always for immediate deployment."},
      { n:66, q:"DC energy efficiency improve karne ke quick wins kya hain?", answer:"Quick (weeks, minimal cost): missing blanking panels (Rs. 500 each, immediate impact), raise CRAC setpoint +2°C (significant energy saving), seal containment gaps (foam/brush seals), decommission zombie servers. Medium (months): smart PDUs for actual load measurement, virtualization consolidation, free cooling activation if economizer exists but not configured. Long-term (1-2yr): high-efficiency chillers, LED lighting, free cooling retrofit.", why:"Practical energy management — cost impacts DC profitability directly.", expectation:"Categorize by time and investment. Give blanking panel vs major CAPEX comparison.", mistake:"Only focusing on CAPEX solutions. Blanking panels + setpoint optimization = PUE 0.15 improvement at zero cost.", tip:"Quick wins ROI: blanking panels + CRAC setpoint + containment = Rs. 50,000 total, PUE 0.15 improvement. Same PUE improvement from cooling equipment = Rs. 50+ lakh."},
      { n:67, q:"Kubernetes Persistent Volume aur PVC kya hote hain?", answer:"PV (Persistent Volume): actual storage resource provisioned by admin. Independent of pod lifecycle. Types: NFS, iSCSI, cloud (EBS, Azure Disk, GCS). PVC (Persistent Volume Claim): storage request by app (size + access mode). K8s matches PVC to available PV. Dynamic provisioning: StorageClass auto-creates PV when PVC created — most common in production. Access modes: ReadWriteOnce (block), ReadWriteMany (NFS/CephFS).", why:"Kubernetes stateful storage is hardest K8s problem. DC engineers must know.", expectation:"Know PV lifecycle independent of pod. Know dynamic provisioning as production approach.", mistake:"Container storage = always ephemeral. StatefulSets + PVCs enable durable storage for databases.", tip:"Wrong access mode = StatefulSet won't schedule. ReadWriteOnce = one node. ReadWriteMany = multiple nodes simultaneously."},
      { n:68, q:"Vendor SLA negotiation mein kya terms include karwane chahiye?", answer:"Uptime: 99.99% power, 99.99% connectivity. Incident response: P1 response 15min, P1 resolution 4hr. Temperature/humidity: ASHRAE A1 within defined % of time. Credits: meaningful (10x hourly rate per breach hour minimum), automatic (not requiring dispute). Rights: audit rights (physical + documentation), escape clause (repeated breaches), data destruction cert on exit. Watch: narrow force majeure definition.", why:"Contract negotiation is senior engineer/manager responsibility.", expectation:"Know metrics beyond uptime. Know credit structure and audit rights.", mistake:"Focus only on uptime %. MTTR, response time, audit rights equally important.", tip:"'Reasonable efforts' language = unenforceable. Require specific measurable commitments with automatic penalties."},
      { n:69, q:"New DC design mein site selection criteria kya hain?", answer:"Power: grid reliability (DISCOM track record, two feeds from different substations), HT availability, renewable access. Connectivity: fiber diversity (2+ ISPs, physically different paths/ducts). Environmental: flood zone (100yr flood map), seismic risk, ambient temperature (cooling cost), water availability (cooling towers). Operational: talent proximity, 24x7 road access (fuel deliveries), expansion land. Regulatory: zoning permits, water use permits.", why:"End-to-end design thinking for senior roles.", expectation:"Cover all utility aspects not just building. Mention fiber physical diversity.", mistake:"Site selected for cost only. Flood risk, fiber path diversity, power quality ignored = long-term pain.", tip:"Fiber diversity: check physical path — two cables in same duct are not diverse regardless of which ISP provides them."},
      { n:70, q:"DC change management process kya hona chahiye?", answer:"Change types: Standard (pre-approved, low risk — cable swap, filter change), Normal (CAB approval — VLAN add, firewall rule, server addition), Emergency (fast-track CAB lead approval — production outage fix). Normal change process: RFC submitted → risk assessment (impact + rollback plan) → CAB review → maintenance window → customer notification → implement + test → post-change verify → close. Rollback plan mandatory for every change.", why:"Change management prevents outages — most DC outages are change-related.", expectation:"Know three change types. Rollback plan as mandatory element.", mistake:"Emergency change = skip all process. Emergency needs faster approval, not zero approval.", tip:"75% of DC outages are change-related. Good change management culture = single biggest uptime improvement."},
    ],
  },

  {
    label: "Scenario Based",
    color: "#dc2626",
    bg: "#fef2f2",
    desc: "Real production situations. Quality of reasoning and prioritization matters most.",
    questions: [
      { n:71, q:"Scenario: Raat 2 baje UPS automatic bypass alarm. Kya karo?", answer:"Bypass = load unprotected. Grid fault = immediate servers down. Run PARALLEL TRACKS: Track A (Risk): grid quality check (multimeter), load check (overload?), immediate customer notification. Track B (Diagnosis): UPS event log download, exact fault code, panel inspection. Do NOT force return to inverter without root cause — if inverter fault, forced transfer = possible power blip. OEM 24x7 hotline with event log ready. Document every action with timestamp.", why:"2 AM operational judgment under stress — real experience tested.", expectation:"Parallel tracks simultaneously. Know NOT to blindly force transfer back.", mistake:"Only call vendor and wait. Must assess immediate risk first.", tip:"After every UPS incident: RCA within 48 hours. Same failure modes repeat across sites without RCA culture."},
      { n:72, q:"Scenario: Rack inlet temperature 35°C (others 22-24°C). Kya karo?", answer:"35°C = thermal throttling risk. PARALLEL troubleshooting: 1. DCIM thermal map — exact rack. 2. Physical walk immediately — missing blanking panels? (80% cause). 3. Cable blocking front airflow? 4. CRAC nearest unit operating? Filter clean? 5. Rack kW vs zone design capacity? 6. Containment breach? Fix in priority order: blanking panels first (Rs. 500, immediate) → cable management → CRAC maintenance → zone capacity review. Monitor 30 min after each fix.", why:"Thermal troubleshooting is daily DC ops — methodical approach tested.", expectation:"Know blanking panels as most common cause. Verify CRAC health as part of diagnosis.", mistake:"Increase CRAC cooling immediately — wasted energy. Rs. 5 blanking panel is the fix 80% of time.", tip:"Thermal camera beats DCIM data for speed. Physical walk reveals issues in minutes."},
      { n:73, q:"Scenario: DG monthly test fail — generator start nahi hua. Grid failure real. UPS 8 min battery. Kya karo?", answer:"Finite runway — PARALLEL TRACKS MANDATORY. Track A (DG): battery voltage check (most common cause), fuel level physical check, fault code, manual crank attempt local panel. Track B (Contingency): ALERT ALL (site manager, customer, senior management), rental DG inquiry immediately, load shedding candidates identify. Timeline: T+0-3min DG diagnosis → T+3-5min if not starting: OEM emergency + rental DG → T+6-7min: non-critical graceful shutdown begin → T+8min: controlled shutdown.", why:"Multi-system failure under time pressure. Tests prioritization.", expectation:"Parallel tracks — cannot focus only on DG when battery has 8 minutes.", mistake:"Focus only on DG, forget load shedding until battery exhausted.", tip:"This is exactly why monthly LOADED DG tests are mandatory. 'Tested last month' means nothing if battery charger failed this week."},
      { n:74, q:"Scenario: UPS at 95%, customer wants 10kW rack. Kya karo?", answer:"95% + 10kW = 105% → UPS trips or auto-bypass → all servers on that UPS down. Cannot proceed as-is. Options: 1. Load shed — move underutilized servers to another UPS (risk: impacts existing customers). 2. Defer deployment — honest customer communication with timeline. 3. Emergency modular UPS expansion — order additional module (2-4 week lead time typically). 4. Alternate UPS if another has capacity and physical path exists. Immediate: internal notification (ops, sales, management) and customer transparency.", why:"Capacity constraint under business pressure — engineering judgment tested.", expectation:"Must refuse to deploy as-is. Present options. Ask why capacity reached 95% without earlier alert.", mistake:"Deploy anyway and hope. 5% headroom + 10kW = guaranteed overload = outage for ALL servers on that UPS.", tip:"Alert threshold: 75% = review new deployments. 80% = capacity team engaged. 95% = deployment freeze."},
      { n:75, q:"Scenario: Complete DC power shutdown for transformer replacement. Planning karo.", answer:"6-8 weeks: scope definition, parallel feed possible?, customer notification (SLA 30-day notice), OEM/contractor scheduling, risk assessment (SPOFs during work), rollback plan. 2 weeks: customer written go/no-go, tools/spares on-site verified, shutdown sequence documented step-by-step, power-up sequence documented (reverse), emergency contacts printed. Day of: safety briefing all, LOTO applied, graceful app shutdown, sequential power-down (apps→servers→storage→network→UPS→LT→HT→transformer). Restoration: reverse order, ALL protection relays re-enabled BEFORE energization.", why:"Major planned maintenance — end-to-end project management tested.", expectation:"Mention insulation resistance test before energization. Must have rollback plan.", mistake:"No rollback plan. New transformer failing at energization — what then?", tip:"Pre-energize checks mandatory: insulation resistance test, turns ratio test, vector group verification. First energization is highest risk moment."},
      { n:76, q:"Scenario: Customer server slow but monitoring shows all green. Kya karo?", answer:"'Monitoring green but slow' = monitoring gap OR application-level issue. Step 1: Quantify 'slow' — 10 second response vs expected 200ms. Step 2: App layer — application logs, slow DB query log, thread pool/connection pool exhaustion. Step 3: Infra correlation — network packet loss/latency (iperf), storage latency at ARRAY level (not server-side), CPU steal time (if VM not just %util), memory swap/page fault rate. Step 4: Monitoring gap — sampling interval (5-min avg hides 1-sec spikes), APM missing?", why:"Multi-layer debugging. Tests going beyond dashboards.", expectation:"Immediately separate infra monitoring from application monitoring. Mention sampling interval as gap.", mistake:"Close ticket because 'monitoring shows green'. Green infra ≠ healthy application.", tip:"APM tools (Datadog APM, Dynatrace) = application-level telemetry. Infrastructure monitoring ≠ APM. Both needed."},
      { n:77, q:"Scenario: Network broadcast storm — DC effectively unusable. Kya immediately karo?", answer:"Time-critical: storm = switch CPU overwhelmed, everything impacted. STEP 1: Find and BREAK THE LOOP FIRST — physical inspection: cable in two ports? Unmanaged switch added? Disconnect suspect ports starting from recently changed area. Storm stops immediately when loop broken. STEP 2 (after storm stops): verify network stable, identify root cause port from switch logs, check STP topology/BPDU Guard config. DO NOT: make config changes during active storm, restart switches (problem returns on boot-up).", why:"Active incident response under pressure — clear thinking tested.", expectation:"Know to find and break loop FIRST before any analysis. Know switch restart won't fix underlying loop.", mistake:"Start config changes during storm — makes debugging harder. Isolate first.", tip:"BPDU Guard on all access ports prevents future storms. One command per port prevents hours of outage."},
      { n:78, q:"Scenario: Fire alarm activated in server room, suppression about to discharge. Kya karo?", answer:"LIFE SAFETY FIRST — no exception. 1. Evacuate ALL personnel immediately. 2. Activate evacuation alarm if anyone remains. 3. DO NOT re-enter to investigate before evacuation complete. 4. Suppression will discharge automatically — do NOT attempt to stop. 5. Call fire department (101) regardless. 6. DO NOT re-enter until: fire department declares safe AND oxygen levels verified (clean agent reduces O2). 7. Notify management and customer simultaneously. NO EQUIPMENT IS WORTH HUMAN LIFE.", why:"Life safety response — non-negotiable protocol.", expectation:"Lead with immediate evacuation without hesitation. Equipment mentioned only after all people accounted for.", mistake:"'Let me check if it's a false alarm first.' Always evacuate — treat every alarm as real.", tip:"VESDA at Alert level = investigate carefully. Conventional smoke alarm = evacuate immediately."},
      { n:79, q:"Scenario: Team member ne bina change management ke production config change kiya. Kya karo?", answer:"Immediate (technical): What changed? Get config diff. Impact? Rollback option — safer to revert or troubleshoot? Stabilize first. Parallel (process): incident ticket opened, stakeholder notification with ETA. Post-incident (people): private conversation same day, SBI model ('In [situation], when you did [behavior], the result was [impact]'). Listen for context — urgency? Process gap? Pattern vs isolated? Root cause: fix person OR fix process (usually process needs fixing too).", why:"Incident response + people management combined. Technical AND leadership response.", expectation:"Separate immediate technical from people response. Look for systemic cause.", mistake:"Public shaming. Private conversation and process review more effective and sustainable.", tip:"Engineers who bypass process often have valid underlying reasons. Fix both the behavior and the process."},
      { n:80, q:"Scenario: AWS Mumbai outage — customer calling. Kya karo?", answer:"Call structure. Opening: 'Thank you for joining. Current status:' Status (5 min): what's down/up, root cause if confirmed ('AWS ap-south-1 regional incident confirmed via AWS Health Dashboard'), what we're doing NOW, ETA only if confident. Accountability: 'We fell short of SLA commitment. SLA credit per contract terms.' Next steps: 'Update every 30 minutes regardless of status.' DO NOT: speculate on cause, blame AWS by name ('upstream dependency'), give vague ETA, technical deep-dive on executive call.", why:"Client escalation handling — career-defining skill.", expectation:"Acknowledge SLA breach directly. Commit to specific update cadence. Factual not emotional.", mistake:"Technical explanation to non-technical customer. They want: what, when, next steps.", tip:"Dedicated communicator role separate from technical resolver during incidents. Split the roles."},
    ],
  },

  {
    label: "Electrical",
    color: "#f59e0b",
    bg: "#fffbeb",
    desc: "Non-IT infrastructure depth — electrical systems, protection, transformers, switchgear.",
    questions: [
      { n:81, q:"HT switchgear mein protection relay kya karta hai?", answer:"Protection relay analyzes CT (Current Transformer) and PT (Potential Transformer) inputs. When configured limits crossed → relay commands circuit breaker to OPEN. The breaker does NOT decide to trip — relay decides, breaker acts. Common functions: OC (51) overcurrent, EF (50N) earth fault, Differential (87) for transformer, Buchholz for oil-immersed transformer. DC context: relays on HT incomer, transformer feeders, bus couplers.", why:"Protection relay is foundational electrical engineering knowledge.", expectation:"Know relay vs breaker roles are separate. Know OC and EF as minimum. Know CTs/PTs supply inputs.", mistake:"Circuit breaker trips automatically on fault. Wrong — relay analyzes, breaker acts on relay command.", tip:"Relay settings file: backup and document before any maintenance. Wrong settings = no protection OR nuisance tripping."},
      { n:82, q:"Transformer oil testing mein kya tests karte hain?", answer:"1. BDV (Dielectric Strength): oil insulation capability, minimum 30kV — below = moisture/contamination. 2. DGA (Dissolved Gas Analysis): gases in oil indicate faults — H2 = partial discharge, C2H2 (acetylene) = ARCING (critical, immediate action), CH4/C2H6 = overheating, CO/CO2 = cellulose degradation. 3. Water content (Karl Fischer): high moisture = reduced BDV. 4. Tan Delta: insulation quality. DGA trending more valuable than single point.", why:"Transformer maintenance knowledge — DGA reveals developing faults before failure.", expectation:"Know DGA specifically. Know acetylene = arcing = critical action required.", mistake:"Oil test = only BDV. DGA is far more diagnostic — reveals developing faults weeks before failure.", tip:"DGA gas ratios (Rogers ratio, Duval triangle) classify fault type. Single gas value without ratio analysis incomplete."},
      { n:83, q:"Earthing system types — TN-S, TN-C, TT kya hain?", answer:"IEC 60364: TN-S: separate N and PE throughout — safest, required for DC. No shared N/PE after supply point. Eliminates noise on earth from neutral currents. TN-C: combined N+PE (PEN conductor) — old systems, NOT suitable for IT equipment. TN-C-S: TN-C from supply, TN-S from main earthing point — common in older buildings. TT: local earth rod, no metallic connection to supply earth. DC mandatory: TN-S.", why:"Earthing system selection directly impacts DC equipment safety and signal quality.", expectation:"Know why TN-S mandatory for DC. Know EMI/noise reason not just safety reason.", mistake:"Any earthing system fine for DC. TN-C creates noise on earth conductor — affects sensitive IT equipment.", tip:"Verify PE and N separated from main earthing terminal when taking over existing DC. Often they're not."},
      { n:84, q:"Busbar trunking vs cable distribution — kab kaun better hai?", answer:"BTS (Busbar Trunking): plug-in tap-offs (expandable without shutdown), faster install, higher current density, better heat dissipation, enclosed (safer). Cable: lower initial cost for fixed installations, better for complex routing, no proprietary system dependency. DC recommendation: BTS for row-level distribution (plug-in expansion critical), cable for fixed infrastructure (transformer to LT panel).", why:"Power distribution design choice for DC electrical engineers.", expectation:"Know plug-in expandability as key BTS advantage. Know it's not always cheaper upfront.", mistake:"BTS always better. For fixed final-load installations — cable can be equally good and cheaper.", tip:"BTS IP rating: IP55 minimum for spray/wash-down risk. IP54 for standard DC environments."},
      { n:85, q:"ATS transfer time aur UPS battery hold-up time ka relationship kya hai?", answer:"Total transfer time = DG start time + ATS transfer time. Typical: DG start to ready = 10-30s. ATS transfer = 20-100ms (mechanical) or <4ms (static STS). Total ≈ 30-40 seconds. UPS battery hold-up time must exceed total transfer time WITH margin. If battery = 10 min, DG starts in 45s = fine. Critical test: actual loaded ATS transfer time must be verified quarterly — nameplate times don't account for aging or fuel issues.", why:"Integration between power systems — critical design verification.", expectation:"Know ATS transfer time is milliseconds (not seconds). Know DG start time is the dominant factor.", mistake:"ATS takes seconds so UPS must have 5+ minutes. ATS transfer <1 second; DG start is the 30-second factor.", tip:"Battery hold-up test annually under actual load. Nameplate runtime ≠ actual runtime with aging batteries."},
      { n:86, q:"LOTO procedure DC mein kaise karte hain?", answer:"1. Prepare: identify all energy sources. 2. Notify: team + customer. 3. Shutdown: proper sequence. 4. Isolate: open isolation switch. 5. Lockout: physical lock on isolation point — KEY WITH WORKING ENGINEER ONLY. 6. Tagout: name + date + work description. 7. Verify: multimeter confirms zero energy — NEVER ASSUME DE-ENERGIZED. 8. Work. Complete: remove tools → working engineer removes their own lock → energize → verify operation. Group LOTO: each engineer applies own lock.", why:"Life safety — no DC electrical work without LOTO.", expectation:"Know verify step is mandatory (test with multimeter). Know only lock owner removes it.", mistake:"Tag only without lock. Tag can be removed by others — lock cannot.", tip:"Group LOTO: work only begins when ALL locks applied. Work complete when ALL locks removed. Never remove another engineer's lock."},
      { n:87, q:"Power factor correction (APFC) kab zaroori hota hai?", answer:"APFC needed when: inductive loads (old motors, old HVAC, non-linear UPS loads) drag PF below target. Utility billing on kVA (not kW): low PF = higher apparent power bill. Many Indian utilities: PF <0.85 = penalty surcharge. How it works: capacitors produce leading reactive power → offsets inductive (lagging) reactive power → PF approaches 1.0. APFC controller monitors PF via CTs, switches capacitor banks auto. Modern DC: modern UPS input PF >0.99 — APFC largely unnecessary in new builds.", why:"Utility cost optimization and electrical system design.", expectation:"Know WHY capacitors correct PF (leading vs lagging reactive). Know modern UPS eliminates need in new DCs.", mistake:"APFC mandatory in all DCs. Modern high-PF UPS makes it unnecessary.", tip:"Check applicable state electricity tariff order for PF penalty provisions before investing in APFC."},
      { n:88, q:"Star-delta starter kya hai aur DC mein motors pe kab use karte hain?", answer:"Problem: 3-phase motors draw 5-7x rated current at startup = trips breakers or causes voltage dip. Star-delta solution: Star (Y): winding voltage = phase/√3 = 240V → current 1/3 of normal. After 5-10s acceleration → switch to Delta (Δ): full 415V → full torque. DC relevance: large cooling tower fans, chiller compressors, pumps — starting without star-delta causes voltage sag affecting UPS input. Modern alternative: VFD (smooth start, better protection, energy saving).", why:"DC has significant motor loads — starting methods affect power quality.", expectation:"Know the 1/3 current reduction in star mode. Know VFD as modern alternative.", mistake:"Star-delta for all motors. VFD superior but more expensive — cost-benefit analysis needed.", tip:"VFD for cooling tower fan = huge energy saving. Fan affinity law: power ∝ speed³. 20% speed reduction = 49% power reduction."},
      { n:89, q:"Arc Flash kya hai aur DC mein kyun relevant hai?", answer:"Arc Flash: electrical explosion from arc discharge. Releases enormous energy: 35,000°C heat, light, pressure wave, molten metal. Incident energy: measured in cal/cm². Hazard boundary determines PPE requirement. DC relevance: HT switchgear maintenance, LT panel work, UPS busbar work. Protection: arc flash study per NFPA 70E (incident energy calculation), PPE per category (Cat 0 = 4 cal/cm², Cat 4 = 40 cal/cm²), arc-rated clothing, face shield. Never work on energized HV without trained personnel.", why:"Life safety — engineers are killed by arc flash in DC environments.", expectation:"Know arc flash is thermal energy explosion — not just shock. Know PPE categories exist.", mistake:"Safety glasses sufficient near electrical panels. Arc flash burns at distance — thermal energy, not just electrical contact.", tip:"Arc flash boundary varies per panel — calculated from fault current and bus impedance. Don't assume same PPE everywhere."},
      { n:90, q:"Neutral conductor DC mein kaise size karte hain?", answer:"Traditional: neutral = phase size (balanced linear loads). DC non-linear loads (UPS, servers, VFDs): generate triplen harmonics (3rd, 5th, 7th). 3rd harmonic currents add in neutral — don't cancel. Neutral can carry 1.7x phase current with 100% triplen harmonics. DC neutral sizing: measure harmonic content first. If THD-I >30%: size neutral at 1.5-2x phase conductor. IT loads: double-sized neutral recommended as standard practice.", why:"DC power quality and cable sizing — specialized electrical engineering.", expectation:"Know non-linear loads cause neutral overcurrent. Know triplen harmonics specifically.", mistake:"Neutral always smaller than or equal to phase. Wrong for non-linear loads — fire risk from undersized neutral.", tip:"Smart PDUs can measure per-circuit neutral current. High neutral current = harmonic problem. Investigate source first."},
    ],
  },

  {
    label: "Cloud",
    color: "#0369a1",
    bg: "#f0f9ff",
    desc: "AWS, Azure, GCP, hybrid cloud, cloud networking.",
    questions: [
      { n:91, q:"AWS VPC kya hai aur traditional LAN se kaise different hai?", answer:"VPC: logically isolated software-defined network in AWS. No physical switches — all software. CIDR range you define. Subnets across multiple AZs. Security Groups: stateful per-instance firewall (default deny, allow only). NACLs: stateless per-subnet ACLs (explicit allow and deny both directions). No broadcast domain (no ARP broadcast). IGW (internet), NAT Gateway (private internet egress), VGW (VPN/Direct Connect). Traditional LAN: physical switches, broadcast domains, hardware firewalls.", why:"Cloud networking fundamentals for hybrid DC engineers.", expectation:"Know VPC is software-defined. Know Security Groups (stateful) vs NACLs (stateless) difference.", mistake:"VPC = just a VLAN. VPC is an entire isolated network with its own routing, security, and connectivity model.", tip:"Security Groups: default deny, allow only. NACLs: stateless — explicit allow AND deny needed for both inbound and outbound directions."},
      { n:92, q:"AWS IAM aur Azure RBAC mein architectural difference kya hai?", answer:"AWS IAM: identity-based policies attached to user/role/group. Resource-based policies on resource (S3 bucket policy). Explicit deny always wins. IAM Role: assumed by EC2/Lambda — no stored credentials. Cross-account via role assumption. Azure RBAC: role assignments at scope (Management Group→Subscription→Resource Group→Resource). Inheritance: higher scope assignments inherited downward. Built-in roles: Owner, Contributor, Reader. Managed Identities = Azure equivalent of IAM Role.", why:"Multi-cloud IAM — essential for engineers managing AWS and Azure.", expectation:"Know role assumption in AWS vs scope-based RBAC in Azure. Know Managed Identity = IAM Role equivalent.", mistake:"IAM same in all clouds. AWS IAM, Azure RBAC, GCP IAM all fundamentally different models.", tip:"Least privilege: start with zero, grant only what's needed. IAM overpermissioning = most common cloud security audit finding."},
      { n:93, q:"AWS Direct Connect aur Azure ExpressRoute mein kya difference hai?", answer:"Both: private dedicated connection from on-prem DC to cloud — bypasses internet. AWS Direct Connect: physical port at DX location (colo), 1Gbps/10Gbps hosted connections. Virtual Interfaces: Private VIF (VPC), Public VIF (AWS services), Transit VIF (TGW). BGP mandatory. Azure ExpressRoute: via connectivity provider or Direct (100Gbps). BGP mandatory. ExpressRoute Global Reach: on-prem to on-prem via Azure backbone. Both: SLA-backed, consistent latency, private.", why:"Hybrid DC cloud connectivity — critical for enterprise engineers.", expectation:"Know both require BGP. Know colo-based connectivity model. Know VIF types (AWS).", mistake:"VPN equivalent to Direct Connect. Internet VPN = variable latency, no SLA, shared bandwidth.", tip:"Direct Connect failover: always configure backup VPN. DX outage + no VPN = isolated cloud — total connectivity loss."},
      { n:94, q:"Kubernetes Pod kya hai? Container se kya different hai?", answer:"Container: single process isolation unit (Docker image → running container). Pod: K8s smallest deployable unit — contains 1+ containers that share network namespace (same IP, communicate via localhost), share storage volumes, always scheduled together. Multi-container pod patterns: Sidecar (logging/monitoring agent alongside main app), Init container (setup before main starts), Ambassador (external proxy). DC: pod = atomic scheduling unit. One IP per pod not per container.", why:"Kubernetes is now DC infrastructure. Pod is fundamental concept.", expectation:"Know pods share network namespace — containers in pod use localhost not separate IPs. Know sidecar pattern.", mistake:"Pod = container. Pod is a wrapper with shared resources. Key operational difference.", tip:"kubectl logs pod/name -c container-name — specify which container when pod has multiple."},
      { n:95, q:"GCP Global VPC uniquely different kyun hai?", answer:"AWS VPC: regional — one VPC per region, peering for cross-region. Azure VNet: regional — cross-region peering possible. GCP VPC: GLOBAL by default — single VPC spans all regions. Subnets are regional (within global VPC). Instances in different regions communicate via internal IPs on same VPC without peering. Private Google Access: GCP APIs without internet gateway. Advantage: no VPC peering complexity for global deployments.", why:"GCP architecture is unique — important for GCP-using engineers.", expectation:"Must state GCP VPC is global (not regional). Know subnets are still regional within global VPC.", mistake:"GCP VPC same as AWS VPC. Fundamental architectural difference.", tip:"GCP Cloud Router for dynamic BGP routing between on-prem and GCP. HA VPN + Cloud Router = preferred connectivity."},
      { n:96, q:"Kubernetes resource requests aur limits kya hote hain?", answer:"Requests: minimum resources guaranteed to container. Scheduler uses for placement decision. Limits: maximum container can use. CPU: compressible — container throttled (not killed) when exceeding limit. Memory: non-compressible — container OOMKilled when exceeding limit. QoS classes: Guaranteed (requests=limits, highest priority), Burstable (requests<limits), BestEffort (no requests/limits, evicted first). Right-sized requests = better bin-packing = higher server utilization.", why:"K8s resource management — critical for production cluster stability.", expectation:"Know CPU is compressible (throttle), memory is not (OOMKill). Know QoS classes.", mistake:"No limits in production. One memory leak crashes entire node by consuming all memory.", tip:"Set requests from actual measured usage (metrics-server). Limits = 2x requests typically as starting point."},
      { n:97, q:"ZTNA kya hai? VPN se better kyun hai?", answer:"ZTNA (Zero Trust Network Access): security model — never trust network location. Every access: identity + device health + context verified. VS VPN: VPN = network-level access (inside VPN = trusted network, wide blast radius). ZTNA = application-level access (authenticated + compliant device → specific app only). DC relevance: remote admin access to DC systems via ZTNA → iDRAC, BMS, DCIM accessible without open VPN. Full audit trail per-application. Products: Zscaler ZPA, Palo Alto Prisma, Cloudflare Access.", why:"Zero trust is modern security architecture replacing perimeter security.", expectation:"Explain why ZTNA is better than VPN for remote access. Know it's application-level not network-level.", mistake:"VPN + strong password = zero trust. Zero trust requires continuous verification not just initial auth.", tip:"ZTNA for DC management: no open management ports, no VPN, granular access, complete audit trail."},
      { n:98, q:"FinOps kya hai aur DC engineer ke liye kyun relevant hai?", answer:"FinOps: financial accountability for cloud spending. Framework: Inform (visibility — who spends what), Optimize (right-sizing, reserved instances, spot), Operate (continuous culture). DC engineer relevance: right-sizing EC2 (over-provisioned = wasted money), Reserved Instances (40-72% savings on committed use), Spot Instances (70-90% cheaper for interruptible), Tagging (cost allocation by team/project), wasted resources (idle EBS volumes, unattached EIPs, old snapshots). Tools: AWS Cost Explorer, CloudHealth.", why:"Cloud cost is now DC infrastructure concern. FinOps-aware engineers more valuable.", expectation:"Know Reserved Instances as main savings mechanism. Know tagging is foundation of cost allocation.", mistake:"FinOps = only finance team concern. Engineers make resource decisions daily that impact the bill.", tip:"Tag policy enforced at AWS org level via Service Control Policies (SCPs). Untagged resource blocking = most effective compliance."},
      { n:99, q:"AWS S3 aur Azure Blob storage mein kya differences hain?", answer:"S3: globally accessible with regional bucket placement. Objects: bucket/key. Storage classes: Standard, Intelligent-Tiering (auto-moves between tiers), Standard-IA, Glacier (Instant/Flexible/Deep Archive). Strong read-after-write consistency. S3 Select: query data without downloading. Azure Blob: Storage Account→Container→Blob hierarchy. Tiers: Hot, Cool, Cold, Archive. Data Lake Gen2: hierarchical namespace for big data. Lifecycle management: auto-tiering policies.", why:"Object storage comparison for multi-cloud DC engineers.", expectation:"Know hierarchy difference. Know lifecycle/tiering in both. Know S3 Intelligent-Tiering.", mistake:"S3 and Blob are equivalent. Integration, pricing, performance characteristics differ significantly.", tip:"S3 Intelligent-Tiering: best for unknown access patterns — auto-moves between tiers based on actual usage."},
      { n:100, q:"Kubernetes namespace kya hai aur multi-tenancy ke liye kaise use karte hain?", answer:"Namespace: logical isolation unit within K8s cluster — virtual cluster within physical cluster. DC multi-tenancy: team isolation (team-a, team-b namespaces), environment isolation (dev/staging/prod), Resource Quotas per namespace (prevent one team consuming all), RBAC per namespace (team-a accesses only team-a namespace), Network Policies (isolate namespace traffic), LimitRange (default resource limits). Limitation: NOT hard isolation — privileged containers can escape namespace boundaries.", why:"K8s multi-tenancy is common DC design challenge.", expectation:"Know namespaces are soft not hard isolation. Mention Resource Quotas and RBAC.", mistake:"Namespaces = complete isolation. Privileged containers can escape namespace isolation.", tip:"Sensitive workloads (security, financial data): separate clusters, not just separate namespaces."},
    ],
  },

  {
    label: "Leadership",
    color: "#6366f1",
    bg: "#eef2ff",
    desc: "People management, vendor relations, escalations, project delivery.",
    questions: [
      { n:101, q:"Team member ne bina authorization ke production change push kiya. Kya karo?", answer:"Immediate (technical first): Is change causing issues? Rollback needed? Stabilize production. Parallel (process): incident ticket opened, stakeholders notified with ETA. People (private conversation, same day): SBI model — 'In [situation], when you did [behavior], result was [impact]'. Listen: urgency? Process gap? Pattern or isolated? Root cause first. Action: process gap → fix process + update training. Clear deliberate violation → document + formal HR discussion. Share lesson with team (no names).", why:"People management + process discipline — tests leadership maturity.", expectation:"Separate technical response from people response. Look for systemic cause, not just individual blame.", mistake:"Immediate public discipline. Private conversation and systemic review more effective.", tip:"Engineers who bypass process often reveal broken processes. Fix both the behavior and the underlying process."},
      { n:102, q:"Client escalation call — 2 hour SLA breach. Kya bologe?", answer:"Opening (2 min): 'Thank you for joining. Current status.' Status (5 min): what's down/up, root cause if confirmed, what we're doing NOW, ETA only if confident. Accountability: 'We fell short of SLA commitment. SLA credit per contract terms.' Next steps: 'Update every 30 minutes regardless of status change.' DO NOT: speculate if cause unconfirmed, technical deep-dive, vague ETA, promise timeline you can't keep.", why:"Client escalation handling — career-defining skill for senior roles.", expectation:"Acknowledge SLA breach directly. Specific update cadence commitment. Factual not emotional.", mistake:"Technical explanation to non-technical customer. They need: what, when, next steps. Not how.", tip:"Designate communicator separate from technical resolver. War room coordinator vs technical lead — split roles."},
      { n:103, q:"Junior engineer repeat mistakes kar raha hai. Kaise handle karoge?", answer:"Step 1: Identify pattern — same mistake or different mistakes? Step 2: Private conversation. SBI model: 'In [situation], when you did [behavior], result was [impact]'. Listen: knowledge gap? Confidence gap? Process gap? Personal issues? Interventions: knowledge gap → structured training + shadowing, confidence gap → supervised practice + gradual responsibility, process gap → update documentation. Define success metric and timeline. Document conversations. Follow up weekly.", why:"People development is core leadership responsibility.", expectation:"Use SBI model or similar structured feedback. Identify root cause of behavior.", mistake:"Avoiding the conversation. 'They'll improve on their own' = wishful thinking that harms everyone.", tip:"Direct respectful feedback is kinder than passive tolerance. Both person and team suffer from avoidance."},
      { n:104, q:"New DC project pe UPS vendor selection kaise karte hain?", answer:"1. Define technical requirements: kVA/kW, PF, topology, modular vs monolithic, battery type, SNMP/API needs. 2. RFP to 3-4 vendors (standardized format for comparison). 3. 10-year TCO: purchase + install + maintenance + energy (efficiency) + battery replacement — NOT lowest purchase price. 4. After-sales service: 24x7 support, on-site engineer response time SLA, parts availability days, local service center. 5. References: 2 operating sites >3 years, talk to operations team not management. 6. Financial stability check.", why:"Vendor selection — senior engineer/manager responsibility.", expectation:"Emphasize TCO over purchase price. Insist on operations team references not management.", mistake:"Lowest bid selection. 10-year UPS TCO often 3x purchase price.", tip:"Ask reference site: 'What would you do differently?' That question reveals real operational issues."},
      { n:105, q:"Operations team ka morale low hai after major incident. Kya karo?", answer:"Immediate post-incident: acknowledge team's effort publicly ('We worked hard under pressure'), RCA focuses on process not person ('System failed'), complete RCA together as team — builds ownership of prevention. Short-term: address legitimate concerns (under-resourced? under-trained?), celebrate what went RIGHT (notification timing, escalation), implement at least one prevention quickly — shows responsiveness. Long-term: blameless post-mortem culture, regular tabletop exercises, recognition for proactive catches.", why:"Leadership under adversity — team management after failure.", expectation:"Distinguish blameless RCA from accountability-free culture. Address both emotional and systemic needs.", mistake:"'Move on, don't dwell on it.' Team needs closure through RCA and visible improvement actions.", tip:"Incident response quality often improves morale more than outcome. Team proud when they handle incident well even if they couldn't prevent it."},
    ],
  },
];

export const ALL_INTERVIEW_QUESTIONS = INTERVIEW_SECTIONS.flatMap((s) =>
  s.questions.map((q) => ({ ...q, section: s.label, color: s.color, bg: s.bg }))
);
